const cfg = $('Config Ready').first().json;
function pick(name) { try { return $(name).first().json; } catch(e) { return { _missing: true, error: String(e.message||e) }; } }
const browser = pick('MarketPlus Browser Status');
const recipe = pick('MarketPlus Recipe Dry-Run');
const seller = pick('OpenMarket Seller Dry-Run');
const limit = pick('Send Limit Status (read-only)');
const sellerOk = seller && seller.ok !== false && !seller._missing && !seller.error;
const recipeOk = recipe && recipe.ok !== false && !recipe._missing;
const browserConnected = !!(browser && (browser.connected === true || browser.ok === true));
return [{
  json: {
    stage: '09-cafe24-openmarket-dry-run',
    dryRunOnly: true,
    productName: cfg.productName,
    productNo: cfg.productNo,
    channelId: cfg.channelId,
    browser: {
      connected: browserConnected,
      note: browser?.note || browser?.error || null,
      tab: browser?.tab || null
    },
    marketPlusRecipeDryRun: {
      ok: !!recipeOk,
      result: recipe
    },
    openMarketSellerDryRun: {
      ok: !!sellerOk,
      message: seller?.message || seller?.error || null,
      credentialReady: seller?.credentialReady,
      readyForLiveAttempt: seller?.readyForLiveAttempt,
      missingSecrets: seller?.missingSecrets || [],
      warnings: seller?.warnings || seller?.plan?.warnings || [],
      received: seller?.received || null,
      plan: seller?.plan || null
    },
    sendLimit: {
      warning: limit?.detail?.sendLimitWarning || limit?.sendLimitWarning || null,
      note: limit?.note || limit?.error || null
    },
    liveBlocked: !(sellerOk && seller?.readyForLiveAttempt !== false && seller?.credentialReady !== false),
    safetyNote: '이 워크플로는 실전송/클릭을 하지 않습니다. readyForLiveAttempt 가 true 여도 n8n에서는 live POST 를 보내지 마세요.',
    nextStep: (!(sellerOk && seller?.readyForLiveAttempt !== false && seller?.credentialReady !== false))
      ? '브라우저 조립공장에서 초안·인증·마켓플러스 화면 검수'
      : '사람이 브라우저에서 최종 확인 후 수동 등록'
  }
}];
